KETING_CONSOLIDATED AS SELECT a.ACCOUNT_NAME ,a.ACCOUNT_ID ,a.CAMPAIGN_NAME ,a.CAMPAIGN_ID ,a.ADSET_NAME ,a.ADSET_ID ,a.AD_ID ,a.AD_NAME ,COALESCE(a.DATE, b.date) date ,a.AD_TYPE ,a.AD_STRENGTH ,a.AD_NETWORK_TYPE ,a.AD_URL ,a.DAY_OF_WEEK ,a.YEAR ,a.MONTH ,UPPER(COALESCE(a.CHANNEL, b.channel)) Channel ,a.ACCOUNT ,a.CLICKS ,a.SPEND ,a.IMPRESSIONS ,a.CONVERSIONS ,a.CONVERSION_VALUE ,a.ADD_TO_CARTS ,a.ADD_TO_CART_VALUE ,a.LANDING_PAGE_VIEWS ,a.INITIATE_CHECKOUTS ,a.INITIATE_CHECKOUTS_VALUE ,b.campaign_name shopify_campaign_name ,DIV0(shopify_revenue, COUNT(1) OVER (PARTITION BY COALESCE(a.date, b.date) ,LOWER(COALESCE(a.campaign_name, b.campaign_name)) ,LOWER(COALESCE(a.channel, b.channel)) ) ) shopify_revenue FROM APPLDATABASE.MAPLEMONK.Alphanso_MARKETING_CONSOLIDATED_INTERMEDIATE a FULL OUTER JOIN (SELECT order_timestamp::date date ,final_utm_campaign campaign_name ,UPPER(CASE WHEN LOWER(final_utm_channel) LIKE ANY (\'%paid social%\',\'%facebook%\', \'%instagram%\',\'%ig%\',\'%fb%\') THEN \'Facebook\' WHEN LOWER(final_utm_channel) LIKE (\'%google%\') THEN \'Google\' END) channel ,SUM(total_sales) shopify_revenue FROM APPLDATABASE.MAPLEMONK.alphanso_DB_SHOPIFY_FACT_ITEMS WHERE channel IS NOT NULL GROUP BY 1,2,3 ) b ON LOWER(a.campaign_name) = LOWER(b.campaign_name) AND a.date = b.date AND LOWER(a.channel) = LOWER(b.channel);",
